/**
 * @brief Example 1: Basic CAN initialization and configuration
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_BasicInit(void)
{
    CAN_Config config = {
        .mode = CAN_OP_MODE_NORMAL,
        .baud_rate = CAN_BAUD_500KBPS,
        .auto_retransmission = true,
        .auto_bus_off_recovery = true,
        .time_triggered_comm = false,
        .prescaler = 9,              /* For 500kbps at 45MHz APB1 */
        .sync_jump_width = 1,
        .time_segment_1 = 13,
        .time_segment_2 = 2
    };

    printf("Initializing CAN with 500kbps baud rate...\n");

    /* Initialize CAN */
    HAL_StatusTypeDef status = CAN_Init(&config);
    if (status != HAL_OK) {
        printf("CAN initialization failed!\n");
        return status;
    }

    printf("CAN initialized successfully\n");
    return HAL_OK;
}

/**
 * @brief Example 2: Configure CAN filters for message reception
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_FilterConfig(void)
{
    CAN_FilterConfig filter_config = {
        .filter_bank = 0,
        .mode = CAN_FILTER_MODE_ID_MASK,
        .scale = CAN_FILTER_SCALE_32BIT,
        .id = EXAMPLE_FILTER_ID,        /* Accept messages with ID 0x100 */
        .mask = EXAMPLE_FILTER_MASK,    /* Mask for first 3 bits */
        .enable = true
    };

    printf("Configuring CAN filter for ID 0x100...\n");

    HAL_StatusTypeDef status = CAN_ConfigFilter(&filter_config);
    if (status != HAL_OK) {
        printf("CAN filter configuration failed!\n");
        return status;
    }

    printf("CAN filter configured successfully\n");
    return HAL_OK;
}

/**
 * @brief Example 3: Transmit a standard CAN frame
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_TransmitStandard(void)
{
    CAN_Frame tx_frame = {
        .id = EXAMPLE_STD_ID,
        .frame_type = CAN_FRAME_STANDARD,
        .data_length = 8,
        .remote_request = false,
        .timestamp = 0
    };

    /* Copy example data */
    memcpy(tx_frame.data, example_data, 8);

    printf("Transmitting standard CAN frame (ID: 0x%03X)...\n", tx_frame.id);

    HAL_StatusTypeDef status = CAN_Transmit(&tx_frame, EXAMPLE_TIMEOUT_MS);
    if (status != HAL_OK) {
        printf("CAN transmission failed!\n");
        return status;
    }

    printf("CAN frame transmitted successfully\n");
    return HAL_OK;
}

