/**
 * @brief Example 6: Receive CAN frames with polling
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_ReceivePolling(void)
{
    CAN_Frame rx_frame;
    uint32_t timeout = 5000; /* 5 second timeout */

    printf("Waiting for CAN frame (polling mode)...\n");

    HAL_StatusTypeDef status = CAN_Receive(&rx_frame, timeout);
    if (status != HAL_OK) {
        if (status == HAL_TIMEOUT) {
            printf("CAN receive timeout - no frame received\n");
        } else {
            printf("CAN receive failed!\n");
        }
        return status;
    }

    /* Display received frame */
    printf("Received CAN frame:\n");
    printf("  ID: 0x%08X (%s)\n",
           (unsigned int)rx_frame.id,
           rx_frame.frame_type == CAN_FRAME_STANDARD ? "Standard" : "Extended");
    printf("  DLC: %d\n", rx_frame.data_length);
    printf("  RTR: %s\n", rx_frame.remote_request ? "Yes" : "No");
    printf("  Data: ");
    for (uint8_t i = 0; i < rx_frame.data_length; i++) {
        printf("%02X ", rx_frame.data[i]);
    }
    printf("\n");

    return HAL_OK;
}

/**
 * @brief Example 7: Setup interrupt-driven reception
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_InterruptSetup(void)
{
    printf("Setting up CAN interrupt callbacks...\n");

    /* Register callbacks */
    CAN_RegisterTxCallback(CAN_TxCallback);
    CAN_RegisterRxCallback(CAN_RxCallback);
    CAN_RegisterErrorCallback(CAN_ErrorCallback);

    /* Enable interrupts */
    HAL_StatusTypeDef status = CAN_EnableInterrupts();
    if (status != HAL_OK) {
        printf("CAN interrupt setup failed!\n");
        return status;
    }

    printf("CAN interrupts enabled successfully\n");
    return HAL_OK;
}

/**
 * @brief Example 8: Get CAN status and statistics
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_GetStatus(void)
{
    HAL_StatusTypeDef status = CAN_GetStatus(&can_status);
    if (status != HAL_OK) {
        printf("Failed to get CAN status!\n");
        return status;
    }

    printf("CAN Status:\n");
    printf("  Initialized: %s\n", can_status.initialized ? "Yes" : "No");
    printf("  TX Mailboxes Free: %d\n", can_status.tx_mailbox_free);
    printf("  RX Messages Pending: %d\n", can_status.rx_messages_pending);
    printf("  Last Error: %d\n", can_status.last_error);
    printf("  Error Count: %d\n", can_status.error_count);
    printf("  TX Count: %d\n", can_status.tx_count);
    printf("  RX Count: %d\n", can_status.rx_count);

    return HAL_OK;
}

/**
 * @brief Example 9: CAN loopback mode for testing
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_LoopbackMode(void)
{
    CAN_Config config = {
        .mode = CAN_OP_MODE_LOOPBACK,
        .baud_rate = CAN_BAUD_500KBPS,
        .auto_retransmission = true,
        .auto_bus_off_recovery = true,
        .time_triggered_comm = false,
        .prescaler = 9,
        .sync_jump_width = 1,
        .time_segment_1 = 13,
        .time_segment_2 = 2
    };

    printf("Initializing CAN in loopback mode...\n");

    /* Initialize CAN in loopback mode */
    HAL_StatusTypeDef status = CAN_Init(&config);
    if (status != HAL_OK) {
        printf("CAN loopback initialization failed!\n");
        return status;
    }

    /* Transmit a test frame */
    CAN_Frame tx_frame = {
        .id = 0x555,
        .frame_type = CAN_FRAME_STANDARD,
        .data_length = 4,
        .remote_request = false,
        .timestamp = 0
    };
    memcpy(tx_frame.data, example_data, 4);

    printf("Transmitting test frame in loopback mode...\n");
    status = CAN_Transmit(&tx_frame, 100);
    if (status != HAL_OK) {
        printf("Loopback transmission failed!\n");
        return status;
    }

    /* Receive the frame */
    CAN_Frame rx_frame;
    status = CAN_Receive(&rx_frame, 100);
    if (status != HAL_OK) {
        printf("Loopback reception failed!\n");
        return status;
    }

    /* Verify received data */
    if (memcmp(tx_frame.data, rx_frame.data, tx_frame.data_length) == 0) {
        printf("Loopback test successful - data matches!\n");
    } else {
        printf("Loopback test failed - data mismatch!\n");
    }

    return HAL_OK;
}

/**
 * @brief Example 10: Error handling and recovery
 * @return HAL_StatusTypeDef HAL status
 */
HAL_StatusTypeDef CAN_Example_ErrorHandling(void)
{
    printf("Demonstrating CAN error handling...\n");

    /* Clear any existing errors */
    HAL_StatusTypeDef status = CAN_ClearErrors();
    if (status != HAL_OK) {
        printf("Error clearing failed!\n");
        return status;
    }

    /* Get current status */
    status = CAN_GetStatus(&can_status);
    if (status != HAL_OK) {
        printf("Status retrieval failed!\n");
        return status;
    }

    printf("Current error count: %d\n", can_status.error_count);
    printf("Last error type: %d\n", can_status.last_error);

    return HAL_OK;
}

