/* Callback function implementations */

/**
 * @brief CAN transmission complete callback
 * @param mailbox Mailbox number that completed transmission
 */
static void CAN_TxCallback(uint8_t mailbox)
{
    printf("CAN TX Callback: Mailbox %d transmission complete\n", mailbox);
}

/**
 * @brief CAN reception callback
 * @param frame Pointer to received CAN frame
 */
static void CAN_RxCallback(const CAN_Frame *frame)
{
    printf("CAN RX Callback: Received frame ID 0x%08X\n", (unsigned int)frame->id);
}

/**
 * @brief CAN error callback
 * @param error Error type
 */
static void CAN_ErrorCallback(CAN_ErrorType error)
{
    printf("CAN Error Callback: Error type %d occurred\n", error);
}
